(window.LADDER_CARDS=window.LADDER_CARDS||{})["13·eng2"]=[{"q": "Heat flow through a slab: q = kAΔT/L. What is the law called?", "a": "Fourier’s law of conduction", "w": ["Newton’s law of cooling", "the Stefan-Boltzmann law", "Ohm’s law"], "why": "Fourier, 1822; k is the thermal conductivity."}, {"q": "Steel has k ≈ 50 W/(m·K). A plate 0.01 m thick, 1 m², with 2 K across it. What is the heat flow?", "a": "10 000 W", "w": ["100 W", "1 W", "250 W"], "why": "50 · 1 · 2/0.01."}, {"q": "L/(kA) for a layer. What is it called?", "a": "its thermal resistance", "w": ["its conductivity", "its heat capacity", "its emissivity"], "why": "Sold per area as an R-value; its inverse is a U-value."}, {"q": "Layers in series have resistances 0.5 and 2 K/W, with 25 K across. What is the heat flow?", "a": "10 W", "w": ["62.5 W", "50 W", "12.5 W"], "why": "Series resistances add: 25/2.5."}, {"q": "Heat carried by a moving fluid. What is that mode called?", "a": "convection", "w": ["conduction", "radiation", "diffusion through a solid"], "why": "The three modes: conduction, convection, radiation."}, {"q": "Power radiated per area by a surface: εσT⁴. What is the law called?", "a": "the Stefan-Boltzmann law", "w": ["Wien’s law", "Fourier’s law", "Planck’s constant"], "why": "Stefan 1879, Boltzmann 1884."}, {"q": "A surface’s absolute temperature doubles. By what factor does its radiated power grow?", "a": "16", "w": ["2", "4", "8"], "why": "T⁴."}, {"q": "ε in εσT⁴, near 1 for black and near 0.03 for polished foil. What is it called?", "a": "emissivity", "w": ["conductivity", "albedo", "resistance"], "why": "Shiny surfaces barely radiate or absorb."}, {"q": "N thin black shields between two black plates in vacuum. By what factor is radiative transfer cut?", "a": "1/(N + 1)", "w": ["1/N", "1/2N", "1/N²"], "why": "Spacecraft multi-layer insulation uses this."}, {"q": "A path of high conductivity through an insulated wall, such as a steel stud. What is it called?", "a": "a thermal bridge", "w": ["a heat sink", "an R-value", "a vapour barrier"], "why": "Parallel paths add their heat flows, so the worst path dominates."}];
