(window.LADDER_CARDS=window.LADDER_CARDS||{})["16·eng2"]=[{"q": "The stress around the circumference of a thin-walled cylinder under internal pressure. What is it called?", "a": "the hoop stress", "w": ["the axial stress", "the shear stress", "the bending stress"], "why": "σ = pr/t."}, {"q": "Thin-walled cylinder, pressure p, radius r, wall t. What is the hoop stress?", "a": "pr/t", "w": ["pr/2t", "2pr/t", "pt/r"], "why": "Balance half the cylinder: p · 2rL = σ · 2tL."}, {"q": "Same cylinder. What is the axial (longitudinal) stress?", "a": "pr/2t", "w": ["pr/t", "pr²/t", "p/2"], "why": "End force pπr² over wall area 2πrt."}, {"q": "A thin cylinder bursts under pressure. Along which line does it split?", "a": "along its length, since the hoop stress is twice the axial", "w": ["around its circumference", "at the end caps only", "in a random direction"], "why": "σ_hoop = 2σ_axial."}, {"q": "Thin-walled sphere, pressure p, radius r, wall t. What is the wall stress?", "a": "pr/2t in every direction", "w": ["pr/t", "pr/4t", "2pr/t"], "why": "Half a cylinder’s hoop stress."}, {"q": "Pressure 2 MPa, radius 0.5 m, wall 10 mm. What is the hoop stress?", "a": "100 MPa", "w": ["50 MPa", "200 MPa", "10 MPa"], "why": "2 · 0.5/0.01."}, {"q": "Hydrostatic pressure at depth d in a liquid of density ρ. What is it?", "a": "ρgd", "w": ["ρd/g", "gd/ρ", "ρg/d"], "why": "About 10⁷ Pa per kilometre of seawater."}, {"q": "A shell under outside pressure folds inward before its material yields. What is the failure called?", "a": "buckling", "w": ["yielding", "fatigue", "creep"], "why": "Deep hulls are thickened against it."}, {"q": "Testing a pressure vessel filled with liquid at above working pressure. What is it called?", "a": "a hydrostatic test", "w": ["a pneumatic test", "a fatigue test", "a leak test by smell"], "why": "Liquid stores far less energy than gas."}, {"q": "Why is a vessel proof-tested with water rather than air?", "a": "compressed gas stores far more energy, so a failure under air is an explosion", "w": ["water is heavier and tests harder", "air corrodes the vessel", "water reaches higher pressure"], "why": "Energy is the area under pressure against volume."}];
